import 'package:flame_audio/flame_audio.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../game/sim/events.dart';

/// Music tracks (`assets/audio/music_<name>.ogg`), generated by tools/audio.
enum Track { title, world1, world2, world3, boss, victory }

/// Short sounds (`assets/audio/sfx_<name>.wav`).
enum Sfx {
  shot,
  laser,
  plasma,
  flame,
  enemyShot,
  hit,
  tink,
  explosion,
  bigExplosion,
  jump,
  land,
  dash,
  knife,
  grenade,
  pickup,
  weapon,
  hostage,
  cassette,
  checkpoint,
  oneUp,
  hurt,
  death,
  tell,
  vehicle,
  eject,
  bossWarn,
  select,
  confirm,
  tick,
  stamp,
  coin,
  scream,
  yeah,
}

/// Jingles (`assets/audio/jingle_<name>.ogg`).
enum Jingle { studio, oneUp, continueQ, gameOver, rankS, stageClear }

abstract interface class AudioService {
  Future<void> init();
  void setVolumes({required double music, required double sfx});
  void sfx(Sfx s);
  void music(Track t);
  void jingle(Jingle j);
  void stopMusic();
  void pauseMusic();
  void resumeMusic();

  /// Plays the right sounds for a simulation event.
  void onSimEvent(SimEvent e);
}

/// Silent implementation for tests and headless runs.
class NoAudio implements AudioService {
  const NoAudio();

  @override
  Future<void> init() async {}
  @override
  void setVolumes({required double music, required double sfx}) {}
  @override
  void sfx(Sfx s) {}
  @override
  void music(Track t) {}
  @override
  void jingle(Jingle j) {}
  @override
  void stopMusic() {}
  @override
  void pauseMusic() {}
  @override
  void resumeMusic() {}
  @override
  void onSimEvent(SimEvent e) {}
}

/// flame_audio implementation with pools for rapid-fire sounds and a
/// per-sound rate limit so big fights don't turn into noise.
class FlameAudioService implements AudioService {
  double _music = 0.7, _sfx = 0.9;
  Track? _current;
  final Map<Sfx, AudioPool> _pools = {};
  final Map<Sfx, int> _lastPlayed = {};
  final Stopwatch _clock = Stopwatch()..start();

  static const _pooled = {
    Sfx.shot,
    Sfx.enemyShot,
    Sfx.hit,
    Sfx.explosion,
    Sfx.tink,
  };

  String _sfxFile(Sfx s) => 'sfx_${s.name}.wav';

  @override
  Future<void> init() async {
    try {
      await FlameAudio.bgm.initialize();
      await FlameAudio.audioCache.loadAll([
        for (final s in Sfx.values) _sfxFile(s),
      ]);
      for (final s in _pooled) {
        _pools[s] = await FlameAudio.createPool(_sfxFile(s), maxPlayers: 4);
      }
    } catch (e) {
      debugPrint('Audio init failed: $e');
    }
  }

  @override
  void setVolumes({required double music, required double sfx}) {
    _music = music;
    _sfx = sfx;
    try {
      FlameAudio.bgm.audioPlayer.setVolume(_music);
    } catch (_) {}
  }

  @override
  void sfx(Sfx s) {
    if (_sfx <= 0) return;
    final now = _clock.elapsedMilliseconds;
    final minGap = _pooled.contains(s) ? 45 : 30;
    if (now - (_lastPlayed[s] ?? -1000) < minGap) return;
    _lastPlayed[s] = now;
    try {
      final pool = _pools[s];
      if (pool != null) {
        pool.start(volume: _sfx);
      } else {
        FlameAudio.play(_sfxFile(s), volume: _sfx);
      }
    } catch (_) {}
  }

  @override
  void music(Track t) {
    if (_current == t) return;
    _current = t;
    try {
      FlameAudio.bgm.play('music_${t.name}.ogg', volume: _music);
    } catch (_) {}
  }

  @override
  void jingle(Jingle j) {
    try {
      FlameAudio.play('jingle_${j.name}.ogg', volume: _sfx);
    } catch (_) {}
  }

  @override
  void stopMusic() {
    _current = null;
    try {
      FlameAudio.bgm.stop();
    } catch (_) {}
  }

  @override
  void pauseMusic() {
    try {
      FlameAudio.bgm.pause();
    } catch (_) {}
  }

  @override
  void resumeMusic() {
    try {
      FlameAudio.bgm.resume();
    } catch (_) {}
  }

  @override
  void onSimEvent(SimEvent e) {
    final s = switch (e.type) {
      SimEventType.shot => switch (e.a) {
        2 => Sfx.laser,
        3 => Sfx.plasma,
        5 => Sfx.flame,
        _ => Sfx.shot,
      },
      SimEventType.enemyShot => Sfx.enemyShot,
      SimEventType.hit => Sfx.hit,
      SimEventType.shieldHit => Sfx.tink,
      SimEventType.explosion => e.a >= 2 ? Sfx.bigExplosion : Sfx.explosion,
      SimEventType.enemyDeath => Sfx.scream,
      SimEventType.playerHurt => Sfx.hurt,
      SimEventType.playerDeath => Sfx.death,
      SimEventType.jump => Sfx.jump,
      SimEventType.land => e.a >= 1 ? Sfx.land : null,
      SimEventType.dash => Sfx.dash,
      SimEventType.melee => Sfx.knife,
      SimEventType.grenadeThrow => Sfx.grenade,
      SimEventType.pickup => Sfx.pickup,
      SimEventType.weaponPickup => Sfx.weapon,
      SimEventType.hostageFreed => Sfx.hostage,
      SimEventType.cassette => Sfx.cassette,
      SimEventType.checkpoint => Sfx.checkpoint,
      SimEventType.oneUp => Sfx.oneUp,
      SimEventType.vehicleEnter => Sfx.vehicle,
      SimEventType.vehicleEject => Sfx.eject,
      SimEventType.bossPhase => Sfx.bossWarn,
      SimEventType.bossDefeated => Sfx.bigExplosion,
      SimEventType.tell => Sfx.tell,
      SimEventType.combo => e.a >= 5 ? Sfx.yeah : null,
      _ => null,
    };
    if (s != null) sfx(s);
  }
}

final audioProvider = Provider<AudioService>((ref) => const NoAudio());
